"""TaskDecomposer — LLM 驱动的任务分解器。

参考 LongHorizon 的任务拆解思想：
- 输入：用户消息 + 可用技能/工具清单
- 输出：子任务列表 + 依赖关系（DAG）
- 复杂度评估：简单任务直接走 process_message，不走拆解

支持两种拆解模式：
1. 线性拆解：子任务按顺序执行
2. DAG 拆解：子任务间有依赖关系，可并行执行无依赖的任务
"""
import json
import logging
import uuid

logger = logging.getLogger("agent.orchestration.decomposer")


# 复杂度评估提示词
_COMPLEXITY_PROMPT = """\
你是一个任务复杂度评估专家。请评估以下用户请求是否需要拆解为多个子任务。

判断标准：
- 简单任务（不需要拆解）：单一意图、可在一步内完成、只涉及一个工具或不需要工具
- 复杂任务（需要拆解）：多步骤、涉及多个工具、有明确阶段、需要中间验证

用户请求：{message}

请以 JSON 格式回复：
{{"complex": true/false, "reason": "简要原因", "estimated_steps": 估计步骤数}}
"""

# 任务拆解提示词
_DECOMPOSE_PROMPT = """\
你是一个任务规划专家。请将以下复杂任务拆解为可独立执行的子任务。

可用技能：{skills}
可用工具：{tools}

用户任务：{message}

请以 JSON 格式回复，每个子任务包含：
{{
  "subtasks": [
    {{
      "id": "sub_1",
      "description": "子任务描述",
      "depends_on": [],
      "expected_output": "预期输出描述",
      "suggested_skill": "建议使用技能名称（可选）",
      "suggested_tools": ["建议使用的工具"]
    }}
  ],
  "final_synthesis": "最终汇总方式描述"
}}

注意：
1. 每个子任务必须可以在新鲜上下文中独立执行
2. depends_on 列出前置子任务的 id（空列表表示无依赖）
3. 子任务粒度适中，每个子任务应可在一次工具调用或一段推理内完成
"""


class SubTask:
    """子任务数据对象。"""

    def __init__(self, id, description, depends_on=None,
                 expected_output='', suggested_skill=None,
                 suggested_tools=None):
        self.id = id
        self.description = description
        self.depends_on = depends_on or []
        self.expected_output = expected_output
        self.suggested_skill = suggested_skill
        self.suggested_tools = suggested_tools or []
        self.status = 'pending'  # pending/running/done/failed/skipped
        self.result = None
        self.evidence = None
        self.token_used = 0

    def to_dict(self):
        return {
            'id': self.id,
            'description': self.description,
            'depends_on': self.depends_on,
            'expected_output': self.expected_output,
            'suggested_skill': self.suggested_skill,
            'suggested_tools': self.suggested_tools,
            'status': self.status,
            'result': self.result,
            'evidence': self.evidence,
            'token_used': self.token_used,
        }

    @classmethod
    def from_dict(cls, data):
        task = cls(
            id=data['id'],
            description=data['description'],
            depends_on=data.get('depends_on', []),
            expected_output=data.get('expected_output', ''),
            suggested_skill=data.get('suggested_skill'),
            suggested_tools=data.get('suggested_tools', []))
        task.status = data.get('status', 'pending')
        task.result = data.get('result')
        task.evidence = data.get('evidence')
        task.token_used = data.get('token_used', 0)
        return task


class TaskPlan:
    """任务计划：包含子任务列表和最终汇总描述。"""

    def __init__(self, original_message, subtasks=None,
                 final_synthesis=''):
        self.original_message = original_message
        self.subtasks = subtasks or []
        self.final_synthesis = final_synthesis
        self.plan_id = 'plan-%s' % uuid.uuid4().hex[:8]

    def to_dict(self):
        return {
            'plan_id': self.plan_id,
            'original_message': self.original_message,
            'subtasks': [t.to_dict() for t in self.subtasks],
            'final_synthesis': self.final_synthesis,
        }

    @classmethod
    def from_dict(cls, data):
        plan = cls(
            original_message=data['original_message'],
            subtasks=[SubTask.from_dict(t) for t in data.get('subtasks', [])],
            final_synthesis=data.get('final_synthesis', ''))
        plan.plan_id = data.get('plan_id', plan.plan_id)
        return plan

    def get_ready_subtasks(self):
        """获取所有依赖已完成的子任务。"""
        done_ids = {t.id for t in self.subtasks if t.status == 'done'}
        return [t for t in self.subtasks
                if t.status == 'pending'
                and all(dep in done_ids for dep in t.depends_on)]

    def is_complete(self):
        """检查所有子任务是否已完成。"""
        return all(t.status in ('done', 'failed', 'skipped')
                   for t in self.subtasks)

    def get_failed_subtasks(self):
        return [t for t in self.subtasks if t.status == 'failed']


class TaskDecomposer:
    """LLM 驱动的任务分解器。"""

    def __init__(self, llm_client, skills_manager, tools_registry):
        self.llm = llm_client
        self.skills = skills_manager
        self.tools = tools_registry

    def assess_complexity(self, message, model=None):
        """评估任务复杂度，返回 (is_complex, reason, estimated_steps)。

        model: None=自动选择, 'fast'=使用快速模型
        """
        try:
            # 默认使用快速模型评估复杂度（省钱省时）
            use_model = model or 'fast'
            response = self.llm.quick_prompt(
                system='你是任务复杂度评估专家。只回复 JSON。',
                user=_COMPLEXITY_PROMPT.format(message=message),
                skill='decompose', category='planning',
                json_mode=True, model=use_model)
            data = json.loads(response)
            return (
                data.get('complex', False),
                data.get('reason', ''),
                data.get('estimated_steps', 1))
        except Exception:
            logger.debug('复杂度评估失败，默认走简单路径', exc_info=True)
            return False, '评估失败', 1

    def decompose(self, message):
        """将复杂任务拆解为子任务列表。

        返回 TaskPlan 实例。
        """
        skills_desc = self._format_skills()
        tools_desc = self._format_tools()

        try:
            response = self.llm.quick_prompt(
                system='你是任务规划专家。只回复 JSON。',
                user=_DECOMPOSE_PROMPT.format(
                    message=message,
                    skills=skills_desc,
                    tools=tools_desc),
                skill='decompose', category='planning',
                json_mode=True)
            data = json.loads(response)
        except Exception:
            logger.exception('任务拆解失败')
            return None

        subtasks = []
        for item in data.get('subtasks', []):
            subtasks.append(SubTask(
                id=item.get('id', 'sub_%d' % (len(subtasks) + 1)),
                description=item.get('description', ''),
                depends_on=item.get('depends_on', []),
                expected_output=item.get('expected_output', ''),
                suggested_skill=item.get('suggested_skill'),
                suggested_tools=item.get('suggested_tools', [])))

        plan = TaskPlan(
            original_message=message,
            subtasks=subtasks,
            final_synthesis=data.get('final_synthesis', ''))

        logger.info('任务已拆解为 %d 个子任务: %s',
                    len(subtasks), plan.plan_id)
        return plan

    def _format_skills(self):
        skills = self.skills.list_skills()
        if not skills:
            return '（无可用技能）'
        return '\n'.join('- %s: %s' % (s['name'], s.get('description', ''))
                         for s in skills)

    def _format_tools(self):
        tools = self.tools.list_tools()
        if not tools:
            return '（无可用工具）'
        return '\n'.join('- %s (%s): %s' % (
            t.get('name', ''), t.get('key', ''),
            t.get('description', '')) for t in tools)
